-- Records of ai_models
-- ----------------------------

-- ----------------------------
-- Table structure for announcement
-- ----------------------------
DROP TABLE IF EXISTS `announcement`;
CREATE TABLE `announcement`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公告标题',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公告内容，支持Markdown或HTML格式',
  `publish_date` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '公告发布时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '公告最后更新时间',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'active' COMMENT '公告状态（如：active、inactive、archived等）',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '公告发布者姓名或昵称',
  `expiration_date` datetime(6) NULL DEFAULT NULL COMMENT '公告过期时间（可选）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_announcemen_title_df0aa9`(`title` ASC, `publish_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1015 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '公告表：用于记录系统公告和通知的信息' ROW_FORMAT = DYNAMIC;

