DROP TABLE IF EXISTS `loan_record`;
CREATE TABLE `loan_record`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `amount` decimal(10, 2) NOT NULL COMMENT '借款金额',
  `interest_rate` decimal(5, 2) NOT NULL COMMENT '年利率',
  `loan_term` int NOT NULL COMMENT '贷款期限（以月为单位）',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'defaulted' COMMENT '贷款状态（如：active、completed、defaulted、overdue等）',
  `repayment_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '还款方式(等额本金/等额本息)',
  `repayment_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已还款金额',
  `repayment_schedule` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '还款计划（如每期还款金额、还款日期等）',
  `usage` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '借款用途',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '收款/还款银行账户',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '贷款申请时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '贷款信息更新时间',
  `user_id` int NOT NULL COMMENT '关联的用户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_loan_record_user_id_5235c2`(`user_id` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `fk_loan_rec_userauth_b20ed31a` FOREIGN KEY (`user_id`) REFERENCES `userauth` (`index`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '贷款记录表：用于记录所有用户的借款信息' ROW_FORMAT = DYNAMIC;

