  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一用户名',
  `full_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '姓名',
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '电话号码',
  `gender` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '性别',
  `id_card_number` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '身份证号',
  `id_card_expiry` date NULL DEFAULT NULL COMMENT '身份证有效期',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '银行卡号',
  `profession` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '职业类别',
  `address` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '住址',
  `date_of_birth` date NULL DEFAULT NULL COMMENT '出生年月',
  `student_verified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '学信网认证，学生专属',
  `profile_picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '头像URL',
  `income` decimal(10, 2) NULL DEFAULT NULL COMMENT '月收入',
  `max_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最大借款额度',
  `credit` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '信用分数',
  `loaned_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已经贷款金额',
  `is_profile_completed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已经完善个人信息',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '记录创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '记录更新时间',
  `user_id` int NOT NULL COMMENT '关联的用户账户',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `username`(`username` ASC) USING BTREE,
  UNIQUE INDEX `user_id`(`user_id` ASC) USING BTREE,
  UNIQUE INDEX `id_card_number`(`id_card_number` ASC) USING BTREE,
  INDEX `idx_user_profil_user_id_e3ff7c`(`user_id` ASC) USING BTREE,
  CONSTRAINT `fk_user_pro_userauth_441faeaa` FOREIGN KEY (`user_id`) REFERENCES `userauth` (`index`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2274 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户基本个人信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_profile
-- ----------------------------

-- ----------------------------
-- Table structure for userauth
-- ----------------------------
DROP TABLE IF EXISTS `userauth`;
CREATE TABLE `userauth`  (
  `index` int NOT NULL AUTO_INCREMENT COMMENT '索引',
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一用户id',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一用户名, 用于登录',
  `phone_number` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一用户电话号码, 用于登录及找回密码',
  `hashed_password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '加密后的密码',
  `role` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'user' COMMENT '用户权限, 分为 user/admin/root',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '注册时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '信息更新时间',
  PRIMARY KEY (`index`) USING BTREE,
  UNIQUE INDEX `id`(`id` ASC) USING BTREE,
  UNIQUE INDEX `username`(`username` ASC) USING BTREE,
  UNIQUE INDEX `phone_number`(`phone_number` ASC) USING BTREE,
  INDEX `idx_userauth_usernam_3f27a1`(`username` ASC, `phone_number` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2284 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户注册信息表：用于登录和找回密码' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of userauth
-- ----------------------------

-- ----------------------------
-- Table structure for userauth_article
-- ----------------------------
DROP TABLE IF EXISTS `userauth_article`;
CREATE TABLE `userauth_article`  (
  `userauth_id` int NOT NULL,
  `article_id` int NOT NULL,
  INDEX `userauth_id`(`userauth_id` ASC) USING BTREE,
  INDEX `article_id`(`article_id` ASC) USING BTREE,
  CONSTRAINT `userauth_article_ibfk_1` FOREIGN KEY (`userauth_id`) REFERENCES `userauth` (`index`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `userauth_article_ibfk_2` FOREIGN KEY (`article_id`) REFERENCES `article` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户推荐的文章' ROW_FORMAT = Dynamic;

