INSERT INTO `announcement` VALUES (1010, '更新通知', '更新通知：我们已上线新版本，修复了若干BUG并提升了支付体验，建议用户尽快更新App以获得最佳体验。', '2025-01-09 23:05:40.691767', '2025-01-09 23:06:57.652706', 'active', '管理员', '2025-01-24 23:06:52.000000');
INSERT INTO `announcement` VALUES (1011, '活动通知', '贷款利率大幅优惠，限时活动现已开启，申请贷款即可享受低至5%的年化利率，赶快行动！', '2025-01-09 23:06:52.084411', '2025-01-09 23:06:52.084411', 'active', '管理员', '2025-02-09 23:06:47.000000');
INSERT INTO `announcement` VALUES (1012, '系统优化', '为提升用户体验，我们进行了系统优化，贷款申请速度将大大提升，感谢您的支持与理解。', '2025-01-09 23:07:33.766950', '2025-01-09 23:07:33.766950', 'active', '管理员', '2025-01-24 23:07:23.000000');
INSERT INTO `announcement` VALUES (1013, '感谢信', '感谢您选择我们，您的信任是我们前进的动力！未来，我们将持续优化服务，助力您的财务管理。', '2025-01-09 23:07:44.123857', '2025-01-09 23:07:54.902525', 'active', '管理员', '2025-02-14 23:07:48.000000');
INSERT INTO `announcement` VALUES (1014, '重要通知', '为确保贷款服务顺畅，系统将于今晚11点进行例行维护，预计停机1小时，请提前做好相关准备', '2025-01-10 00:01:36.265219', '2025-01-10 00:01:36.265234', 'active', '管理员', '2025-01-31 00:00:00.000000');
INSERT INTO `article` VALUES (109, '贷款：现代金融的支柱', '贷款在现代金融体系中扮演着关键角色，为个人和企业提供资金支持以实现各种目标。从买房、购车到创业，贷款为人们提供了实现梦想的途径。然而，贷款也伴随着责任，借款人需要了解利率、还款计划和信用评分等因素，以确保财务健康。', '周建川', '2025-01-09 23:10:53.383511', '2025-01-09 23:10:53.383527', 'published', NULL, '本文探讨了贷款的双重角色及其对个人和企业的影响。', 0);
INSERT INTO `article` VALUES (110, '小微企业贷款：破解融资难题', '小微企业融资难一直是经济发展的痛点。本文分析了小微企业贷款面临的挑战，并提出了金融机构如何通过创新产品和服务支持小微企业发展的解决方案。', '王芳', '2025-01-09 23:11:25.171749', '2025-01-09 23:11:25.171767', 'published', NULL, '本文聚焦小微企业融资困境，探讨金融机构如何通过创新贷款模式助力小微企业成长。', 0);
INSERT INTO `article` VALUES (111, '绿色金融：贷款与可持续发展的桥梁', '绿色金融正在成为全球金融行业的重要趋势。本文介绍了绿色贷款的概念，探讨了如何通过贷款政策推动环境保护和可持续发展。', '张伟', '2025-01-09 23:11:50.626488', '2025-01-09 23:11:50.626516', 'published', NULL, '本文阐述了绿色金融的重要性，展示了贷款政策如何成为推动环境保护和可持续发展的关键工具。', 0);
INSERT INTO `article` VALUES (112, '个人信用贷款：提升信用评分的实用指南', '信用评分是获得贷款的关键因素。本文提供了提升信用评分的实用建议，包括合理使用信用卡、按时还款等，帮助读者更容易获得贷款。', '陈静', '2025-01-09 23:12:16.721100', '2025-01-09 23:12:16.721117', 'published', NULL, '本文为读者提供了提升信用评分的实用技巧，助力个人更轻松地获得贷款和更好的金融服务。', 0);
INSERT INTO `article` VALUES (113, '区块链技术：重塑贷款行业的未来', '区块链技术正在改变贷款行业的传统模式。本文探讨了区块链如何提高贷款流程的透明度和安全性，并分析了其潜在挑战。', '刘强', '2025-01-09 23:12:41.191454', '2025-01-09 23:12:41.191472', 'published', NULL, '本文解析了区块链技术在贷款行业的应用前景，展示了其如何提升贷款流程的效率和安全性。', 0);
